SELECT p.PROJECT_ID AS project_id,p.PROJECT_CODE AS project_code,p.TIMEZONE AS timezone
FROM CFG_PROJECTS p WHERE p.ACTIVE_FLAG='Y' AND (EXISTS (SELECT 1 FROM AUD_CFG_PIPELINES_HISTORY h  WHERE h.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_TASKS_HISTORY h JOIN CFG_PIPELINES owner ON owner.PIPELINE_ID=h.PIPELINE_ID WHERE owner.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_TASK_PARAMETERS_HISTORY h JOIN CFG_TASKS t ON t.TASK_ID=h.TASK_ID JOIN CFG_PIPELINES owner ON owner.PIPELINE_ID=t.PIPELINE_ID WHERE owner.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_TASK_DEPENDENCY_HISTORY h JOIN CFG_PIPELINES owner ON owner.PIPELINE_ID=h.PIPELINE_ID WHERE owner.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_PIPELINE_DEPENDENCY_HISTORY h JOIN CFG_PIPELINES owner ON owner.PIPELINE_ID=h.PIPELINE_ID WHERE owner.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_BUSINESS_RULES_HISTORY h JOIN CFG_PIPELINES owner ON owner.PIPELINE_ID=h.PIPELINE_ID WHERE owner.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_TABLES_HISTORY h  WHERE h.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:')
OR EXISTS (SELECT 1 FROM AUD_CFG_COLUMNS_HISTORY h JOIN CFG_TABLES owner ON owner.TABLE_ID=h.TABLE_ID WHERE owner.PROJECT_ID=p.PROJECT_ID AND substr(h.ACTOR,1,4)='sql:'))
ORDER BY p.PROJECT_ID
